from pathlib import Path
import json,html
ROOT=Path(__file__).resolve().parent
manifest=json.loads((ROOT/'manifest.json').read_text());names=[i['name'] for i in manifest['icons'] if i['direction']=='a']
vectors={v:{n:(ROOT/'svg'/v/(n+'.svg')).read_text() for n in names} for v in ['a','b','c']}
def icon(n):return '<span class="icon" aria-hidden="true" data-icon="'+n+'"></span>'
def button(n,label='',cls='',aria=None):return '<button type="button" class="'+('touch '+cls)+'" aria-label="'+html.escape(aria or label or n)+'">'+icon(n)+(('<span>'+label+'</span>') if label else '')+'</button>'
home='<header><strong>bemem.</strong>'+button('search',cls='bare')+'<div class="spacer"></div>'+button('account',cls='circle bare')+'</header>'
cards='<div class="canvas"><div class="sample-card">t<small>Test Member</small></div><div class="sample-mini">Sample</div></div>'
toolbar='<div class="rail decorate-rail"><button class="touch" aria-label="Cancel decorating">Cancel</button>'+button('undo',aria='Undo last decoration or card move')+button('redo',aria='Redo last undone action')+button('save','Save','primary')+'</div>'
symbols=['pet-paw','travel-suitcase','wellness-flower','cafe-coffee','shopping-bag','savings-piggy']
selector='<div class="collections">'+''.join('<button class="category" aria-label="'+label+'"><img alt="" src="../../assets/decorations/cozy-cute-v1/'+id+'.png"></button>' for id,label in zip(symbols,['Pet & Care','Travel Diary','Wellness','Café Day','Shopping & Gifts','Little Savings']))+'</div>'
grid='<div class="paging">'+''.join(button('previous',aria='Previous artwork page') if i==0 else button('next',aria='Next artwork page') if i==23 else '<div class="thumb" aria-hidden="true"><img alt="" src="../../assets/decorations/cozy-cute-v1/'+symbols[i%6]+'.png"></div>' for i in range(24))+'</div>'
mockups=[('Home header',home+cards,'Search remains frameless; Account48dp; wordmark remains unchanged.'),
 ('Account popup',home+'<div class="menu">'+''.join(button(n,label) for n,label in [('add-card','Add Card'),('decorate','Decorate'),('policy','Policy'),('login','Login')])+'</div>','Four existing menu labels retained. Leading icons are a review proposal.'),
 ('Decorate toolbar','<header><b>Decorate</b><span class="spacer"></span><small>Cozy Cute</small></header>'+cards+toolbar+selector,'Same Cancel / Undo / Redo / Save order. Only Undo/Redo lose visible labels in this proposal.'),
 ('Decorate pagination','<header><b>Decorate</b></header>'+cards+toolbar+selector+grid,'Eight columns × three rows, navigation remains inside the grid. No resize handle/footer.'),
 ('Card Detail','<div class="detail"><div class="detail-head"><b>Test Member</b>'+button('share',aria='Share card')+'<span class="spacer"></span>'+button('close',cls='circle',aria='Close card detail')+'</div><div class="code-panel"><div class="scan-glyph">'+icon('barcode')+'</div><small class="scan-note">Mockup only · not scannable</small><div class="code-tools"><small id="format-label">Code 128</small>'+button('qr',cls='code-toggle',aria='Show QR Code')+'</div></div><div class="preview-row"><small>EXP: No<br>Expiry</small><div class="member-card"><b>Test Member</b></div><div class="side-control">'+button('flip-front',cls='flip-toggle',aria='Switch card front and back')+'<small id="side-label">Front</small></div></div><div class="member-number">00123456</div>'+button('journal','View Card History & Receipts','wide')+'</div>','Home context shows Share; Create uses the same slot for Edit. Card is6×4 blocks,28dp unit,0.1-block inset,14dp corners.'),
 ('Photo Journal controls','<div class="journal"><div class="detail-head"><b>History & Receipts</b><span class="spacer"></span>'+button('close',cls='circle',aria='Close history')+'</div><p>Test Member</p><div class="entry-row"><div class="photos"><span>1</span><span>2</span><span>3</span><span>4</span></div><div><small>11/11/2026</small><p>A sample note</p><small>4 photos</small></div></div><div class="journal-space"></div><div class="rail">'+button('previous','Back to Card')+button('add-photo','Add Photo','primary')+'</div></div>','Home journal footer retained. Create-only Select / Select All / Delete Selected remain labeled; see inventory, not added here.')]
panels=''.join('<article><h3>'+name+'</h3><div class="phone">'+body+'</div><p class="caption">'+note+'</p></article>' for name,body,note in mockups)
page='''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>bemem Signature Minimal · design review</title><style>
:root{--ink:#263943;--canvas:#f4f5f7;--line:#ccd4db;--action:#405764}*{box-sizing:border-box}body{margin:0;color:var(--ink);background:#e9edf0;font:15px system-ui}main{max-width:1260px;margin:auto;padding:24px}h1{font-size:29px;letter-spacing:-1px}h2{margin-top:32px}p{line-height:1.5}a{color:inherit}nav,.links,.switches{display:flex;gap:8px;flex-wrap:wrap}button,a.tab{font:inherit;color:inherit;cursor:pointer}button{border:1px solid var(--line);border-radius:14px;background:#fff;min-height:48px;padding:10px 14px;display:inline-flex;align-items:center;justify-content:center;gap:8px}button[aria-pressed=true]{background:#dde5eb;border-color:#506674}button:focus-visible,a:focus-visible{outline:3px solid #263943;outline-offset:3px}button:active{opacity:.72}button:disabled{opacity:.38;cursor:default}.notice{padding:12px 16px;background:#f8fafb;border-radius:14px}nav{position:sticky;top:0;z-index:4;padding:12px 0;background:#e9edf0}.icon{display:inline-flex;width:24px;height:24px;flex:none;align-items:center;justify-content:center}.icon svg{width:100%;height:100%;color:inherit;overflow:visible}.catalog{display:grid;grid-template-columns:repeat(auto-fit,minmax(108px,1fr));gap:10px}.tile{background:#f7f8fa;border:1px solid #d7dce0;border-radius:14px;padding:16px 5px;text-align:center;min-width:0}.tile>.icon{width:32px;height:32px}.tile small{display:block;margin-top:12px;overflow-wrap:anywhere}.sizes{display:flex;align-items:center;gap:12px;justify-content:center;margin-top:14px}.sizes .icon{width:var(--size);height:var(--size)}.sizes b{font-size:10px;font-weight:400;display:block;margin-top:4px}.inverse{background:var(--ink);color:white}.boards{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:12px}.boards img{width:100%;height:auto}.boards a{display:block}.mocks{display:grid;grid-template-columns:repeat(auto-fit,minmax(330px,1fr));gap:26px;align-items:start}.phone{max-width:390px;width:100%;margin:auto;background:var(--canvas);border:1px solid #c8d2d9;border-radius:24px;overflow:hidden}.caption{max-width:390px;margin:12px auto;font-size:13px}header{display:flex;align-items:center;gap:4px;padding:14px 20px 8px;min-height:70px;flex-wrap:wrap}header strong{font-size:30px;letter-spacing:-1.2px;font-weight:800;line-height:38px;white-space:nowrap}header .bare{padding:0;background:transparent;border:0;box-shadow:none}header .circle{border:1px solid var(--line);border-radius:50%}.spacer{flex:1}.touch{min-width:48px;min-height:48px}.touch:not(:has(span:not(.icon))){padding:0}.canvas{height:240px;margin:16px;position:relative}.sample-card{width:162.4px;height:106.4px;background:#aac4bc;border-radius:14px;padding:14px;font-size:28px}.sample-card small{display:block;font-size:13px;margin-top:25px}.sample-mini{position:absolute;left:168px;top:0;width:78px;height:50px;background:#b38d9f;border-radius:14px;padding:12px;font-size:12px}.menu{width:224px;margin:8px 20px 24px auto;background:#f7f7fa;border:1px solid var(--line);border-radius:20px;padding:6px 0;box-shadow:0 8px 24px #23303c29}.menu button{width:100%;border:0;background:transparent;border-radius:0;justify-content:flex-start;padding:12px 20px}.rail{display:flex;gap:4px;padding:8px 12px 4px}.rail button{font-size:12px;flex:1;min-width:0;padding:8px 5px}.rail .icon{width:20px;height:20px}.primary{background:var(--action);color:#fff;border-color:var(--action)}.collections{display:flex;padding:0 8px}.category{width:calc(100% / 6);aspect-ratio:1;padding:2px;min-height:0;background:none;border:0;opacity:.48}.category:first-child{opacity:1}.category img{width:100%;max-width:56px;aspect-ratio:1;object-fit:contain}.paging{display:grid;grid-template-columns:repeat(8,minmax(0,1fr));gap:2px;padding:8px}.paging>*{height:34px;min-height:0;min-width:0;padding:0;border-radius:10px}.paging button{border-width:2px}.thumb{display:grid;place-items:center;border:1px solid var(--line)}.thumb img{width:28px;height:28px;object-fit:contain}.detail{padding:20px 20px 20px;background:#f7f7fc;border-radius:24px 24px 0 0}.detail-head{display:flex;gap:4px;align-items:center;margin-bottom:16px}.detail-head b{font-size:18px}.detail-head button{border:0;background:transparent}.detail-head .circle{background:#fff;border:1px solid var(--line);border-radius:50%}.code-panel{position:relative;background:#fff;border-radius:20px;min-height:194px;padding:16px 16px 60px;text-align:center}.scan-glyph>.icon{width:230px;height:100px}.scan-note{display:block;font-size:10px}.code-tools{display:flex;position:absolute;bottom:4px;left:16px;right:8px;align-items:center;justify-content:space-between}.code-tools button{border:0;background:#f3f5f6}.preview-row{display:flex;align-items:center;justify-content:space-between;gap:4px;margin-top:8px}.preview-row>small{font-size:11px;line-height:18px;min-width:48px}.member-card{width:162.4px;height:106.4px;background:#a8bdc5;border-radius:14px;flex:none;padding:10px;font-size:12px}.side-control{display:flex;flex-direction:column;align-items:center;min-width:48px}.side-control button{padding:0}.side-control small{font-size:11px}.member-number{text-align:center;font-size:22px;letter-spacing:2px;margin:8px}.wide{width:100%;font-size:13px;padding:10px 6px}.journal{padding:20px;min-height:540px;display:flex;flex-direction:column}.entry-row{display:flex;gap:10px;align-items:center;border-bottom:1px solid var(--line);padding-bottom:16px}.entry-row p{font-size:12px;margin:5px 0}.entry-row small{font-size:11px}.photos{display:flex;gap:3px}.photos span{width:34px;height:48px;background:#b8c6ce;border-radius:3px;display:grid;place-items:center}.journal-space{flex:1;min-height:200px}.journal .rail{padding:0;justify-content:space-between}.states{display:flex;gap:12px;flex-wrap:wrap}.states figure{margin:0;text-align:center}.states figcaption{font-size:12px;margin-top:8px}.selected{background:#dce5e9}.danger{color:#a33338}.legend{font-size:13px}.dark-test{background:var(--ink);color:white;padding:16px;border-radius:14px}.mock-status{font-size:12px;min-height:20px} @media(max-width:700px){main{padding:14px}.boards{grid-template-columns:1fr}.mocks{grid-template-columns:1fr}.catalog{grid-template-columns:repeat(3,minmax(0,1fr))}.tile{padding:12px 2px}.sizes{gap:6px}.phone{border-radius:18px}}@media(max-width:350px){.preview-row{flex-wrap:wrap;justify-content:center}.catalog{grid-template-columns:repeat(2,minmax(0,1fr))}}
</style></head><body><main><h1>bemem Signature Minimal</h1><p>Review-only functional icon exploration · Pearl Gray — Lagoon Glass · no app changes.</p><div class="notice">Choose A/B/C to compare the same43 canonical proposals.72 source-backed action groups are mapped in the inventory. Conventional metaphors are retained; these drawings do not establish legal exclusivity.</div>
<nav aria-label="Design direction"><button data-direction="a" aria-pressed="true">A · Precision Rounded</button><button data-direction="b" aria-pressed="false">B · Soft Organic</button><button data-direction="c" aria-pressed="false">C · bemem Signature</button></nav><div class="links"><a href="ICON-INVENTORY.md">Source-backed inventory</a><a href="DESIGN-SPEC.md">Design specification</a><a href="DESIGN-REVIEW.md">Evaluation & recommendation</a><a href="validation.json">Validation</a></div>
<h2>Three contact sheets</h2><div class="boards">BOARDS</div><h2>Same-action comparison</h2><a href="sheets/comparison.png"><img style="max-width:840px;width:100%" src="sheets/comparison.png" alt="Same actions across three directions"></a><h2 id="active-title">A · Precision Rounded</h2><p class="legend">Each tile shows32 CSS px, then16/20/24/32 CSS px. At browser100% zoom these are logical review units, not physical Samsung pixels or a native dp measurement. Labels are for design review.</p><div class="catalog" id="catalog"></div><h2>Inverse small-size checks</h2><div class="dark-test" id="inverse"></div>
<h2>Existing-layout mockups</h2><p class="legend">Manually reconstructed from current UI code for icon review, not native screenshots. Synthetic Test Member /00123456 only. No controls save or access phone data. Six category illustrations remain unchanged.</p><div class="mocks">PANELS</div><p class="mock-status" id="mock-status" aria-live="polite">Mockup controls provide review feedback only.</p><h2>Interaction states</h2><div class="states" id="states"></div><p class="legend">Single-color vector in every state. Semantic destructive ink is an optional context color, paired with text/confirmation; the vector geometry is identical. Disabled actions must not run.</p><a href="sheets/states.png">Full A/B/C state sheet</a><h2>Actual-size PNG boards</h2><div class="links">ACTUAL</div><p>Next: choose a direction; refine selected glyphs and label decisions before any production integration.</p></main><script>
const vectors=VECTORS,names=NAMES;let direction='a',format='barcode',side='front';const titles={a:'Precision Rounded',b:'Soft Organic',c:'bemem Signature'};
function iconHTML(name){return vectors[direction][name]||vectors[direction].info}function paint(){document.querySelectorAll('[data-icon]').forEach(el=>{el.innerHTML=iconHTML(el.dataset.icon)});document.getElementById('active-title').textContent=direction.toUpperCase()+' · '+titles[direction];document.querySelectorAll('[data-direction]').forEach(b=>b.setAttribute('aria-pressed',b.dataset.direction===direction?'true':'false'))}
function build(){const catalog=document.getElementById('catalog');catalog.replaceChildren();for(const name of names){const tile=document.createElement('div');tile.className='tile';tile.innerHTML='<span class="icon" aria-hidden="true" data-icon="'+name+'"></span><small>'+name+'</small><div class="sizes">'+[16,20,24,32].map(size=>'<div><span aria-hidden="true" class="icon" data-icon="'+name+'" style="--size:'+size+'px"></span><b>'+size+'</b></div>').join('')+'</div>';catalog.append(tile)}document.getElementById('inverse').innerHTML=['search','account','edit','qr','barcode','flip-front','select-all'].map(name=>'<div class="tile inverse" style="display:inline-block;margin:5px"><small>'+name+'</small><div class="sizes">'+[16,20,24,32].map(size=>'<span class="icon" aria-hidden="true" data-icon="'+name+'" style="--size:'+size+'px"></span>').join('')+'</div></div>').join('');const states=document.getElementById('states');states.innerHTML=['Default','Pressed','Selected','Disabled','Destructive','Inverse'].map(state=>'<figure><button '+(state==='Disabled'?'disabled ':'')+'class="touch '+(state==='Selected'?'selected':state==='Destructive'?'danger':state==='Inverse'?'primary':'')+'" aria-label="'+state+' Save example" '+(state==='Pressed'?'style="opacity:.72"':'')+'><span class="icon" aria-hidden="true" data-icon="'+(state==='Destructive'?'delete':state==='Selected'?'select':'save')+'"></span><span>'+(state==='Destructive'?'Delete':'Save')+'</span></button><figcaption>'+state+'</figcaption></figure>').join('');paint()}
document.querySelectorAll('[data-direction]').forEach(button=>button.addEventListener('click',()=>{direction=button.dataset.direction;paint()}));
document.querySelector('.code-toggle').addEventListener('click',event=>{format=format==='barcode'?'qr':'barcode';document.querySelector('.scan-glyph .icon').dataset.icon=format;document.querySelector('.code-toggle .icon').dataset.icon=format==='qr'?'barcode':'qr';document.querySelector('.code-toggle').setAttribute('aria-label',format==='qr'?'Show Code128':'Show QR Code');document.getElementById('format-label').textContent=format==='qr'?'QR Code':'Code128';paint()});
document.querySelector('.flip-toggle').addEventListener('click',()=>{side=side==='front'?'back':'front';document.querySelector('.flip-toggle .icon').dataset.icon=side==='front'?'flip-front':'flip-back';document.querySelector('.flip-toggle').setAttribute('aria-pressed',side==='back'?'true':'false');document.getElementById('side-label').textContent=side==='front'?'Front':'Back';document.querySelector('.member-card').style.background=side==='front'?'#a8bdc5':'#bdc8d2';paint()});
document.querySelectorAll('.mocks button').forEach(b=>b.addEventListener('click',()=>{document.getElementById('mock-status').textContent='Design preview: '+b.getAttribute('aria-label')+'. No wallet data or app action was triggered.'}));build();
</script></body></html>'''
boards=''.join('<a href="sheets/'+v+'-contact.png"><img alt="'+name+' icon contact sheet" src="sheets/'+v+'-contact.png"></a>' for v,name in [('a','Precision Rounded'),('b','Soft Organic'),('c','bemem Signature')])
page=page.replace('BOARDS',boards).replace('PANELS',panels).replace('ACTUAL',''.join('<a href="sheets/'+v+'-actual-size.png">'+v.upper()+' · light and dark16/20/24/32px</a>' for v in ['a','b','c'])).replace('VECTORS',json.dumps(vectors)).replace('NAMES',json.dumps(names))
page=page.replace('#a33338','#b42318')
palette=json.loads((ROOT.parents[1]/'design-system/bemem-lagoon-glass-rc2/TOKENS.json').read_text(encoding='utf-8'))['palettes']['pearl-gray']['colors']
page=page.replace('--canvas:#f4f5f7','--canvas:'+palette['canvas']['base'])
page=page.replace('<style>','<style>@font-face{font-family:BememManrope;src:url("../../assets/fonts/lagoon/manrope.ttf") format("truetype");font-display:swap}body{font-family:BememManrope,system-ui!important}.decorate-rail>button:nth-child(1){width:60px;flex:none}.decorate-rail>button:nth-child(2),.decorate-rail>button:nth-child(3){width:56px;flex:none}')
(ROOT/'index.html').write_text(page,encoding='utf-8')
print('Offline gallery:3 directions,43 icons,6 existing-layout mockups, states and scale checks')
